import json
import logging
import re
from typing import Dict, Any

from app.core.config import settings
from app.platform.capabilities.binding import provider
from app.platform.llm import call_llm, resolve_agent_model, resolve_agent_temperature
from app.platform.publication_gate.review import (
    APPROVAL_THRESHOLD,
    REVIEW_NOT_VERIFIED,
    REVIEW_OK,
)

logger = logging.getLogger(__name__)


# Generated by GitHub Copilot
async def run_revisor(state: Dict[str, Any]) -> Dict[str, Any]:
    """
    Revisor Agent.
    Evaluates the draft paper using Ollama, returning an approval score (0-100)
    and structured feedback. A score below 80 triggers a redraft loop.
    """
    draft_text = state.get("draft_text") or ""
    loop_count = state.get("loop_count") or 0
    log = state.get("_log") or (lambda msg, level="info": None)

    # Resolve model: provider-aware per-agent resolution (SPEC-023/T12.3)
    agent_cfg = (state.get("agent_settings") or {}).get("revisor", {})
    model = resolve_agent_model("revisor", state.get("agent_settings"))
    # Temperatura del agente (perfil o ajustes de la ejecución). Hasta ahora se
    # guardaba y no llegaba a ningún proveedor: era un control de la interfaz
    # que no hacía nada.
    temperature = resolve_agent_temperature("revisor", state.get("agent_settings"))

    logger.info(f"Running Revisor Agent with model: {model}")
    log(f"👁️ Evaluando borrador — modelo: {model} | iteración: {loop_count + 1} | {len(draft_text.split())} palabras")

    prompt = (
        f"Identity: You are a Senior Software Engineer Expert in LLMOps and multi-agent systems.\n"
        f"Exact technology stack: Python, FastAPI, LangGraph (v2), Qdrant and a local inference engine (like Ollama/vLLM).\n\n"
        f"You are acting as a peer reviewer for a scientific journal. Evaluate the following draft.\n\n"
        f"Draft Content:\n{draft_text}\n\n"
        f"Evaluate the draft for scientific rigor, clarity, structure, academic style, and especially "
        f"COHERENCE (does it stay on-topic, are the arguments internally consistent, do the sections "
        f"connect logically and is it grounded rather than vague/hallucinated?).\n"
        f"You must return your evaluation in JSON format. Do not write markdown blocks before the JSON.\n"
        f"The JSON MUST match this schema:\n"
        f'{{\n  "approval_score": <int between 0 and 100>,\n'
        f'  "coherent": <true or false>,\n'
        f'  "feedback": [<list of string review comments>]\n}}\n\n'
        f"JSON output:"
    )

    # SPEC-032/AC15: sin una revisión interpretable el estado es `not_verified`.
    # Ni se aprueba por defecto (el 85 de antes) ni se inventa una revisión: lo que
    # no se puede comprobar no se aprueba.
    approval_score = 0
    coherent = False
    feedback: list = []
    review_status = REVIEW_NOT_VERIFIED
    motivo = ""

    try:
        evaluar = provider(state, "llm", call_llm)
        raw_response = await evaluar(
            prompt, model=model, timeout=45.0, num_ctx=4096, keep_alive=0,
            temperature=temperature,
        )
        json_match = re.search(r"\{.*\}", raw_response or "", re.DOTALL)
        if not json_match:
            motivo = "la respuesta no contiene un JSON"
        else:
            try:
                data = json.loads(json_match.group(0))
                score = data.get("approval_score")
                if isinstance(score, bool) or not isinstance(score, (int, float)) or not 0 <= score <= 100:
                    motivo = f"approval_score ausente o fuera de 0–100 ({score!r})"
                else:
                    approval_score = int(score)
                    coherent = bool(data.get("coherent", True))
                    feedback = data.get("feedback", [])
                    if not isinstance(feedback, list):
                        feedback = [str(feedback)]
                    review_status = REVIEW_OK
            except Exception as parse_err:
                motivo = f"JSON no interpretable: {parse_err}"
    except Exception as e:
        motivo = f"fallo del LLM: {e}"

    if review_status != REVIEW_OK:
        logger.error("Revisor: revisión no verificada — %s", motivo)
        approval_score = 0
        coherent = False
        feedback = []

    # The draft "fails coherence" when the reviewer says so or the score is low.
    coherent = coherent and approval_score >= APPROVAL_THRESHOLD
    new_loop_count = loop_count + 1 if approval_score < APPROVAL_THRESHOLD else loop_count

    if review_status != REVIEW_OK:
        log(f"⚠️ Revisión no verificada ({motivo}): no se aprueba ni se inventa una puntuación.", "warning")
    elif coherent:
        log(f"✅ Borrador aprobado — puntuación: {approval_score}/100")
    else:
        log(f"❌ Coherencia insuficiente — puntuación: {approval_score}/100.", "warning")
        for fb in feedback:
            log(f"  → {fb}")

    result: Dict[str, Any] = {
        "approval_score": approval_score,
        "feedback": feedback,
        "loop_count": new_loop_count,
        "coherent": coherent,
        "review_status": review_status,
        # Always reset the per-pass decision so a stale value can't re-trigger routing.
        "user_decision": None,
    }

    # ── Human-in-the-loop: on incoherence, ask the user whether to add a source
    # or continue. Only when a live decision channel is available (SSE listener).
    request_decision = state.get("_request_decision")
    source_retries = state.get("source_retries") or 0
    MAX_SOURCE_RETRIES = 3

    # Una revisión no verificada no es una opinión sobre la coherencia: no se le
    # pregunta a la persona si añade una fuente por ella.
    if not coherent and review_status == REVIEW_OK and request_decision is not None:
        if source_retries >= MAX_SOURCE_RETRIES:
            log("ℹ️ Límite de reintentos con nuevas fuentes alcanzado — continuando con el borrador actual.", "warning")
            result["user_decision"] = "continue"
        else:
            log("⏸️ Esperando decisión del usuario: subir otra fuente o continuar...", "warning")
            decision = await request_decision({
                "reason": "coherence_failed",
                "approval_score": approval_score,
                "feedback": feedback[:5],
                "message": "El revisor considera que la redacción no es suficientemente coherente.",
            })
            result["user_decision"] = decision
            if decision == "add_source":
                result["source_retries"] = source_retries + 1
                log("📥 El usuario añadió una nueva fuente — reejecutando la investigación.")
            else:
                log("▶️ El usuario decidió continuar con el borrador actual.")

    return result
